import sys
def transform(s):
    vowels = set("aeiouAEIOU"); res = []; cnt = 1
    for ch in s:
        if ch in vowels:
            res.append(str(cnt)); cnt = cnt % 9 + 1
        else:
            res.append(ch)
    return "".join(res)
if __name__ == "__main__":
    s = sys.stdin.readline().rstrip("\n").rstrip("\r")
    print(transform(s))

