import sys
def is_prime(x):
    if x < 2: return False
    i = 2
    while i*i <= x:
        if x % i == 0: return False
        i += 1
    return True
def otp(a, b):
    primes = [x for x in range(a, b+1) if is_prime(x)]
    if not primes: return 0
    return max(primes) + min(primes)
if __name__ == "__main__":
    d = sys.stdin.read().split(); a = int(d[0]); b = int(d[1])
    print(otp(a, b))

